(2298, 858, '_lp_requirements', 'a:7:{i:0;s:84:\"Vir disputatum depingere viros opinor nequiter anteponam dant genere convincunturque\";i:1;s:111:\"Sententiam visus docet philosophiam moveatur habitare sedeat darei sicut anulum tot cupiditas explanetur amotio\";i:2;s:100:\"Diodorus occultum illi nesciebam suus ortus aut stabile sempiternam satietate sanabat ipsi discedere\";i:3;s:123:\"Pulchritudo aliquem prope vesperum darei illuc concordiae seiuncta fingeres videtis ordiamur regulum beatiorem statui autem\";i:4;s:107:\"Praeclarae amicitiam putes vesperum labefactare disputationibus hominem honestum adulter inchoavit confidit\";i:5;s:101:\"Antiochum interficit moderatio iudicabis inchoavit contemnendis virtutum sicut instituendarum zenonis\";i:6;s:96:\"Primisque vitium vixerit aetatulis reguli risu cor ponere putet quamquam tale philosophi aliquem\";}'),
(2299, 858, '_lp_target_audiences', 'a:9:{i:0;s:111:\"Exilem dimicabit honestatis percipitur miserrimus corpore tuetur quos leonidas rogavi dicuntur civitatis magnam\";i:1;s:120:\"Evolare mitigari accesseris alios mea omittamus aequius quosdam defecerit totas philosophiae multarum dominorum tarentum\";i:2;s:85:\"Venissem percipiendas grata dignos expectata modicum formosum sequitur probavit aliis\";i:3;s:105:\"Acies imperio praecepta relinqueret conatum elaboratum divitiis ancillae sempiternam nondum elit nascitur\";i:4;s:91:\"Virtutibus omnis roga dicerem corporis restatis secundae velle instituendarum plebis firmum\";i:5;s:93:\"Signum alia prave quaero sanabat veniendi festinanter melius diligentissime posui disciplinae\";i:6;s:91:\"Inquis oratores delectant fortis proverbia vitiose recusant inconstantissime necne delectat\";i:7;s:122:\"Refers vel perpetuam speculis profuso acute regem natalem retinere plebis homines hominibus minime splendidior redarguitur\";i:8;s:99:\"Opera volo aristonem opertarum imperitos sine dubia signum dignissimum conferam pleniorem academiae\";}'),
(2300, 858, '_lp_key_features', 'a:9:{i:0;s:99:\"Tutiorem uno pietatem natalis omnibus animal gravius corroborati discordia extrinsecus potero simus\";i:1;s:69:\"Omnino q aequius sensibus sine sordidos fictas dissentit omnem quodam\";i:2;s:114:\"Praestantissimum videro fortem poteris intellegit additis oppressum contemnet secundae consideret facio percipitur\";i:3;s:100:\"Disciplina consequentia sensitque amotio liceat datum pater uno tributa pleniorem agas velint vellet\";i:4;s:137:\"Detractis gerendarum consentit amici translatum partem respondere audax quadratum poterit stulti gravissimo pervertere dominorum opifices\";i:5;s:92:\"Iucunditatem nesciam accessit cyrenaicos mediocri disserendo deesse possent diogenem dicitis\";i:6;s:120:\"Tacet oportebit verecunde philosophis vartutis gaudio omnisque incidunt dissimiles color putabit munus considerata licet\";i:7;s:99:\"Timore invidiosum longam posse illum repellant iacet posui digna disceptari permansurum maxime vere\";i:8;s:91:\"Codrum video solemus longissimus ullo celebrari libero so necopinato fruitur sapienti bonis\";}');
INSERT INTO `wp_NguyenDuyHieppostmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(2301, 858, '_lp_faqs', 'a:11:{i:0;a:2:{i:0;s:89:\"Vincitur valitudo tenueris dicam potestne ponis satis dicturam ipsis villa media serpere?\";i:1;s:174:\"<p>Modestiam obscuris moveor praecepta filio poterit tollitur nec summum es coronae dicuntur quidam</p><p>Usum postea proverbia mali quae nescius magister illae commutare</p>\";}i:1;a:2:{i:0;s:114:\"Honestatem ante reperies verso inchoatum similes severitatem animalibus istis comparatio promerem putaverunt ames?\";i:1;s:215:\"<p>Pudebit dis subicias stultost salebra loquar dubitabit actus accidisset moveatur insipientium eiusdem permulcet arcesilas diodorus refellatur vincitur futtiles</p><p>Poterit perturbatio maxima infelix lapathi</p>\";}i:2;a:2:{i:0;s:77:\"Sustinebit antea certum rem pluribus tribunus saepius caecitas sapientes cum?\";i:1;s:202:\"<p>Ultimas locis virtutis homini animi boni abundaret iudicium pugnant brevem dustmata musicis peccata confirmatae eligant liquidius pudoris excelsiores ielunior</p><p>Amicitias ille fere ceteri die</p>\";}i:3;a:2:{i:0;s:99:\"Solebam deceat intellegetur dolendi ennius infantes reperire esset aequas stuprata alio utilitatem?\";i:1;s:207:\"<p>Illius summam confusio videmusne erigimur malane vulgo sese neglegendi vesperum illorum vixerit contritum superiori videmus iniurasque loqui selectio levare</p><p>Reliquis percipiet lustravit ielunior</p>\";}i:4;a:2:{i:0;s:120:\"Distinguitur mercedem aequius oratores irrideatur dissensione magis adiunxit platone contritum dexteram corpore virtuti?\";i:1;s:180:\"<p>Arcesilas illum musicis appellant viri eandem socrates vides utebare veni</p><p>Video dolori secrevit valitudo temperantiam peti declinavi subicias huic turpis amores anulum</p>\";}i:5;a:2:{i:0;s:85:\"Fabulas morbus formam dicere mos nullam potest privasse potuerit acerrimus adhibebat?\";i:1;s:198:\"<p>Aliena danda corpusne malitiam ponatur meo praestantissimum aequabilesque conveniant pervenit ingenuas vultum</p><p>Factum honesto illuc uterque periculum nolo gravis manliana oboediens egone</p>\";}i:6;a:2:{i:0;s:77:\"Istarum isdem satisfacit facto dantur constructio mutat dixit anulum solemus?\";i:1;s:201:\"<p>Ludimur egregio laudarem intellegit salebra confecimus magnarum permulcet viderere postulet nullus sapienti beatus legerint</p><p>Futuri senescit quo quaerimus locus hebes motum iucunda gloriosa</p>\";}i:7;a:2:{i:0;s:92:\"Liber laudatum opinor definitio cur doleas gignit viderentur audiunt desideraret dissimiles?\";i:1;s:247:\"<p>Pylades possum definitio crede destitero imperatores memoriae oratores polliceretur roges ludus commovere</p><p>Dicitur iocabor faciant utilitatem plane dictum caecitas dicet ususque multos faceret uberiora doctorum vocatur vidit haerebitis</p>\";}i:8;a:2:{i:0;s:83:\"Possumus vestigium estquod superabat currit mavis serpere audax adiit amantissimus?\";i:1;s:284:\"<p>Habebit familiaris opportune recuso appellamus tuum themistocles iucundi recusant nesciebat suave</p><p>Audeo displicuit saneque amantissimus mala doloris pertimuit crimen saneque prorsus disputationibus levamentum necesse huius secrevit</p><p>Similis reliquarum totam animoque</p>\";}i:9;a:2:{i:0;s:122:\"Grata fortitudinis locuples reliquorum umquam fortior narrare antiochum tua videndum signa macello vitiorum epicuri statu?\";i:1;s:173:\"<p>Nesciam dicet theophrasto negotii apertis quem stoicorum quaerenda magnitudine meministi cari academia maxime</p><p>Obiit stabilem quo inter vitabis perpetua quicquid</p>\";}i:10;a:2:{i:0;s:92:\"Mutat consuetudinem minime poterant habentur erit plures nostrae praeceptis mehercule eodem?\";i:1;s:218:\"<p>Stultorum perfici via concedis unaque progressionis sapiens dixti persequi quonam aliquando</p><p>Neutrum beatissimum conatum levem comitetur quaesivit moderatio praestantia sint deprehensus iustus advesperascit</p>\";}}'),
(2302, 858, '_lp_featured_review', 'Tyrannus eadem officio agi isdem l eiuro oderit dignissimum ante tiberina vis conclusum vilissimis litteram extra putet vos debuerunt vituperanda vellem quicquid percipitur convincunturque iudicia vix tuetur aliam probat obsequor habebat ipse'),
